'use strict'

// Generated by vfs_scaffold_auth. Sessions: a random 32-byte token lives only in the visitor's cookie; the database
// keeps its SHA-256, so a leaked table cannot be replayed. Sliding expiry: every use pushes the end date forward.

const crypto = require('node:crypto')
const config = require('./config')
const store = require('./store')

const COOKIE = 'app_session'
const TTL_MS = config.sessionDays * 24 * 60 * 60 * 1000
// Extend the session at most once an hour, not on every request.
const SLIDE_AFTER_MS = 60 * 60 * 1000
const SAFE_PREFIX = /^\/[A-Za-z0-9._~\-/]*$/

const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex')
const hashToken = (token) => sha256(String(token))

function newToken() {
  const token = crypto.randomBytes(32).toString('base64url')
  return { token, id: hashToken(token) }
}

const firstHeaderValue = (req, name) => String(req.headers[name] || '').split(',')[0].trim()

/** The cookie is scoped to the prefix the app is served under (the preview sends it as X-Forwarded-Prefix). */
function cookiePath(req) {
  const prefix = firstHeaderValue(req, 'x-forwarded-prefix')
  if (!prefix || !SAFE_PREFIX.test(prefix) || prefix.includes('//') || prefix.split('/').includes('..')) return '/'
  return prefix.replace(/\/+$/, '') || '/'
}

const isHttps = (req) => req.secure === true || firstHeaderValue(req, 'x-forwarded-proto').toLowerCase() === 'https'

function cookieHeader(req, value, maxAgeSeconds) {
  const parts = [`${COOKIE}=${value}`, `Path=${cookiePath(req)}`, `Max-Age=${maxAgeSeconds}`, 'HttpOnly', 'SameSite=Lax']
  if (maxAgeSeconds === 0) parts.push('Expires=Thu, 01 Jan 1970 00:00:00 GMT')
  if (isHttps(req)) parts.push('Secure')
  return parts.join('; ')
}

/** Every `app_session` value the browser sent (one per matching cookie path, most specific first). */
function readTokens(req) {
  const tokens = []
  for (const pair of String(req.headers.cookie || '').split(';')) {
    const index = pair.indexOf('=')
    if (index < 0 || pair.slice(0, index).trim() !== COOKIE) continue
    const value = pair.slice(index + 1).trim()
    if (/^[A-Za-z0-9_-]{20,100}$/.test(value)) tokens.push(value)
  }
  return tokens.slice(0, 3)
}

async function startSession(req, res, userId) {
  const { token, id } = newToken()
  const now = Date.now()
  await store.createSession({ id, userId, expiresAt: new Date(now + TTL_MS), createdAt: new Date(now) })
  res.append('Set-Cookie', cookieHeader(req, token, Math.floor(TTL_MS / 1000)))
}

/** The signed-in user ({ id, email, name, roles }) or null. Slides the expiry and refreshes the cookie when due. */
async function loadUser(req, res) {
  for (const token of readTokens(req)) {
    const id = hashToken(token)
    const session = await store.findSession(id)
    if (!session) continue
    const now = Date.now()
    const expiresAt = new Date(session.expiresAt).getTime()
    if (!(expiresAt > now)) {
      await store.deleteSession(id)
      continue
    }
    const user = await store.getUser(session.userId)
    if (!user || user.disabled) {
      await store.deleteSession(id)
      continue
    }
    if (expiresAt - now < TTL_MS - SLIDE_AFTER_MS) {
      await store.touchSession(id, new Date(now + TTL_MS))
      if (res && !res.headersSent) res.append('Set-Cookie', cookieHeader(req, token, Math.floor(TTL_MS / 1000)))
    }
    return { id: user.id, email: user.email, name: user.name, roles: user.roles, sessionId: id }
  }
  return null
}

async function endSession(req, res) {
  for (const token of readTokens(req)) await store.deleteSession(hashToken(token))
  res.append('Set-Cookie', cookieHeader(req, '', 0))
}

module.exports = { COOKIE, TTL_MS, newToken, hashToken, cookiePath, cookieHeader, isHttps, readTokens, startSession, loadUser, endSession }
